+let rendering = false;

 const $ = (sel) => document.querySelector(sel);

-function add(title) {
-  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
+// Fills {title} as plain text: a function replacer, so "$&" or "$1" in a title stay as typed.
+const withTitle = (template, title) => template.replace('{title}', () => title);
+
+function add(title, dueDate) {
+  const t = { id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() };
+  if (isValidDueDate(dueDate)) t.dueDate = dueDate; // an empty field adds no key (AC2); a past date is fine (A4)
+  todos.push(t);
   commit();
 }

@@ -21,39 +31,138 @@ function remove(id) {
   commit();
 }

+// On a row's date `change`. Only a valid, different date is saved. An empty value (a part being retyped with the
+// keyboard) does nothing here, so it never drops a saved date; leaving the field decides (Q3). Returns the todo if saved.
+function setDue(id, value) {
+  const t = todos.find((x) => x.id === id);
+  if (!t || !isValidDueDate(value) || t.dueDate === value) return null;
+  t.dueDate = value;
+  save();
+  changedInPlace = true;
+  return t;
+}
+
+// On leaving a row's date field while it is empty. `before`: the field's value when it got focus. Returns true if saved.
+function clearDue(id, before) {
+  const t = todos.find((x) => x.id === id);
+  if (!t || !isValidDueDate(t.dueDate)) return false; // nothing shown to clear; a broken value stays as it is (A14)
+  const old = t.dueDate; // the date saved now, which may be one set during this same focus
+  delete t.dueDate;
+  const notSaved = persist(store, todos).message;
+  // Set and cleared within this focus: the customer loses no date they had before, so no D5 and no Undo (Q3).
+  if (before === '') {
+    show(notSaved);
+    return true;
+  }
+  offerUndo(notSaved || withTitle(DUE_TEXT.cleared, t.title), () => {
+    const again = todos.find((x) => x.id === id);
+    if (again) again.dueDate = old;
+  });
+  return true;
+}
+
 function commit() {
-  show(persist(store, todos).message);
+  save();
   render();
 }

+function save() {
+  show(persist(store, todos).message);
+}
+
+// Every new message removes the Undo button, so add, toggle, delete, a date change and import all end it (A16);
+// filter, sort and leaving a date field show nothing, so it stays.
 function show(message) {
+  clearUndo();
   $('#message').textContent = message || '';
 }

+// One Undo for the whole app (plan Q7): restore() puts the data back; saving and redrawing are done here.
+function offerUndo(message, restore) {
+  show(message);
+  $('#undo').hidden = false;
+  undo = { restore, timer: setTimeout(clearUndo, 10000) };
+}
+
+function clearUndo() {
+  if (undo) clearTimeout(undo.timer);
+  undo = null;
+  $('#undo').hidden = true;
+}
+
 function visible() {
-  if (filter === 'open') return todos.filter((t) => !t.done);
-  if (filter === 'done') return todos.filter((t) => t.done);
-  return todos;
+  let shown = todos;
+  if (filter === 'open') shown = todos.filter((t) => !t.done);
+  if (filter === 'done') shown = todos.filter((t) => t.done);
+  return sort === 'due' ? sortByDue(shown) : shown; // a new array: the saved order never changes (Q6)
