+function showDue(li, t, today) {
+  const overdue = isOverdue(t, today);
+  li.className = [t.done ? 'done' : '', overdue ? 'overdue' : ''].filter(Boolean).join(' ');
+  li.querySelector('.due').textContent = isValidDueDate(t.dueDate) ? formatDueDate(t.dueDate) : '';
+  li.querySelector('.overdue-tag').textContent = overdue ? DUE_TEXT.overdue : '';
+}
+
+function row(t, today) {
+  const li = document.createElement('li');
+  li.dataset.id = t.id;
+  // A fixed template with no user text; the title, label and dates go in below as text or attributes (S3).
+  li.innerHTML =
+    `<label><input type="checkbox" class="toggle" ${t.done ? 'checked' : ''}> <span class="title"></span></label>` +
+    '<span class="due-box"><input type="date" class="due-input"><span class="due"></span><span class="overdue-tag"></span></span>' +
+    '<button class="remove" aria-label="Xoá">×</button>';
+  li.querySelector('.title').textContent = t.title;
+  const box = li.querySelector('.toggle');
+  const date = li.querySelector('.due-input');
+  const del = li.querySelector('.remove');
+  // So render() can put focus back on the same control of the same todo.
+  for (const [el, part] of [[box, 'toggle'], [date, 'due-input'], [del, 'remove']]) {
+    el.dataset.id = t.id;
+    el.dataset.part = part;
+  }
+  box.onchange = () => toggle(t.id);
+  del.onclick = () => remove(t.id);
+  date.value = isValidDueDate(t.dueDate) ? t.dueDate : '';
+  date.setAttribute('aria-label', withTitle(DUE_TEXT.rowLabel, t.title));
+  date.onfocus = () => { date.dataset.before = date.value; };
+  date.onchange = () => {
+    const changed = setDue(t.id, date.value);
+    if (changed) showDue(li, changed, localDateString(new Date()));
+  };
+  date.onblur = (e) => {
+    if (rendering) return; // a browser may blur a field while render() removes it
+    if (date.value === '' && clearDue(t.id, date.dataset.before)) changedInPlace = true;
+    if (changedInPlace) render(e.relatedTarget);
+  };
+  showDue(li, t, today);
+  return li;
 }

-function render() {
+// focusTarget: where focus is going, when called from a blur (the browser has not moved focus yet at that point).
+function render(focusTarget) {
   const list = $('#list');
+  const from = focusTarget || document.activeElement;
+  const keep = from && from.dataset && from.dataset.part ? { id: from.dataset.id, part: from.dataset.part } : null;
+  const today = localDateString(new Date()); // again on every draw (F3 step 5)
+  let refocus = null;
+  rendering = true;
   list.innerHTML = '';
   for (const t of visible()) {
-    const li = document.createElement('li');
-    li.className = t.done ? 'done' : '';
-    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
-    li.querySelector('span').textContent = t.title;
-    li.querySelector('input').onchange = () => toggle(t.id);
-    li.querySelector('button').onclick = () => remove(t.id);
+    const li = row(t, today);
+    if (keep && keep.id === t.id) refocus = li.querySelector(`.${keep.part}`);
     list.append(li);
   }
+  rendering = false;
+  changedInPlace = false;
   const open = todos.filter((t) => !t.done).length;
   // Every todo done (and the list not empty): say so instead of "0 việc chưa xong" (Thảo, PR 3).
   $('#count').textContent = open === 0 && todos.length > 0 ? 'Đã xong hết' : `${formatCount(open)} việc chưa xong`;
   $('#unreadable').hidden = !store.readError;
   // Based on the whole list, not the filter; and not shown on a read error, where the list only looks empty.
   $('#empty').hidden = todos.length > 0 || store.readError;
+  if (refocus) refocus.focus();
 }

 // Resolves true only when the customer picks "Thay"; Esc and "Huỷ" resolve false.
