 $('#add').onsubmit = (e) => {
   e.preventDefault();
   const input = $('#title');
-  if (input.value.trim()) add(input.value);
+  const date = $('#due');
+  if (input.value.trim()) add(input.value, date.value);
   input.value = '';
+  date.value = '';
 };

