@@ -82,6 +193,20 @@ $('#filters').onclick = (e) => {
   render();
 };

+$('#sort').value = sort; // a browser may restore the last choice on reload; the list starts in added order (A11)
+$('#sort').onchange = () => {
+  sort = $('#sort').value === 'due' ? 'due' : 'added';
+  render();
+};
+
+$('#undo').onclick = () => {
+  if (!undo) return;
+  undo.restore();
