diff --git a/app/style.css b/app/style.css
index fc3eb87..6587dc7 100644
--- a/app/style.css
+++ b/app/style.css
@@ -1,12 +1,23 @@
 body { font: 16px/1.5 system-ui, sans-serif; background: #f6f6f4; color: #222; margin: 0; }
 main { max-width: 32rem; margin: 3rem auto; padding: 0 1rem; }
-form { display: flex; gap: .5rem; }
-input#title { flex: 1; padding: .5rem; }
-nav { margin: 1rem 0; display: flex; gap: .25rem; }
+form { display: flex; flex-wrap: wrap; gap: .5rem; align-items: center; }
+input#title { flex: 1 1 12rem; padding: .5rem; }
+#due-label, #sort-label { display: flex; align-items: center; gap: .35rem; }
+#view { margin: 1rem 0; display: flex; flex-wrap: wrap; gap: .5rem 1rem; align-items: center; justify-content: space-between; }
+nav { display: flex; gap: .25rem; }
 nav button.on { font-weight: 700; }
 ul { list-style: none; padding: 0; }
-li { display: flex; justify-content: space-between; padding: .4rem 0; border-bottom: 1px solid #ddd; }
-li.done span { text-decoration: line-through; color: #888; }
+li { display: flex; flex-wrap: wrap; align-items: center; gap: .25rem .5rem; padding: .4rem 0; border-bottom: 1px solid #ddd; }
+li > label { flex: 1 1 10rem; }
+li.done .title { text-decoration: line-through; color: #888; }
+.due-box { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem; font-size: .875rem; }
+.due { color: #444; }
+.due:empty, .overdue-tag:empty { display: none; }
+/* Overdue is said in words ("Quá hạn"), the colour only adds to it (U5). #a4161a on #f6f6f4: contrast about 7:1. */
+li.overdue { border-left: 3px solid #a4161a; padding-left: .5rem; }
+li.overdue .due, .overdue-tag { color: #a4161a; }
+.overdue-tag { font-weight: 700; }
+#undo { margin: .25rem 0 .5rem; }
 .banner { background: #fff4e5; border: 1px solid #d08a2a; border-radius: 4px; padding: .6rem .8rem; }
 #message { background: #eaf1fb; border-radius: 4px; padding: .5rem .8rem; }
 #message:empty { display: none; }

